    expect(chat.state.streaming).toBe(false)
    expect(chat.state.recovery?.kind).toBe('run_interrupted')
    expect(approvalsApi.list).toHaveBeenCalledWith({ run_id: 'run-1', status: 'all', limit: 50 })
  })

