```ts
/**
 * 执行一次重连：先 GET run 回填/校验，再按状态决定终态收尾、审批恢复或重发流。
 *
 * 不得走 startStream：它会重置 lastSeq/process/runId，回放事件会被当成新 run
 * 重复处理（设计 4.2 B4）。
 */
async function performReconnect(): Promise<void> {
  const attempt = lastAttempt.value
  const runId = state.value.runId
  if (!attempt || !runId) {
    enterDegraded('连接已断开，缺少可恢复的运行信息。', null)
    return
  }
  if (reconnectInFlight) return
  reconnectInFlight = true
  controller?.abort()
  const currentController = new AbortController()
  controller = currentController
  reconnectController = currentController

  try {
    // 重连前必须先回填 conversation_id：新会话可能已创建 run 但前端还没收到
    // conversation.created，直接重发会让后端新建会话/run（设计 4.2 B2）。
    const run = await runsApi.get(runId)
    if (currentController.signal.aborted) return
    if (state.value.runId !== runId || run.id !== state.value.runId) {
      // 用户已切走或 run 被替换：不再占用当前会话的流。
      enterDegraded('运行状态已变化，已停止自动重连。', null)
      return
    }

    state.value = {
      ...state.value,
      conversationId: run.conversation_id,
      runId: run.id,
      runStatus: run.status,
    }

    if (isTerminal(run.status)) {
      // 服务端已经结束：补历史 + 审批对账，不需要再连流。
      resetReconnectBudget()
      connection.value = 'idle'
      state.value = { ...state.value, streaming: false }
      setRecovery(null)
      void reconcileRunApprovals(run.id, run.status)
      await refreshHistory().catch(() => undefined)
      return
    }

    if (run.status === 'interrupted') {
      // HITL：没有可跟随的活动流，回到审批横幅 + 轮询。
      clearReconnect()
      connection.value = 'degraded'
      state.value = {
        ...state.value,
        streaming: false,
        recovery: {
          kind: 'run_interrupted',
          code: 'run_interrupted',
          message: '该运行正在等待审批；批准或拒绝后会自动继续。',
          runId: run.id,
          runStatus: 'interrupted',
          retryable: false,
        },
      }
      await syncPendingApprovals(run.id)
      schedulePolling(run.id)
      return
    }

    // running / queued：用回填后的 conversation_id + 原幂等键重发流。
    await openChatStream(
      {
        conversation_id: run.conversation_id,
        message: attempt.text,
        client_message_id: attempt.clientMessageId,
        ...attempt.context,
      },
      {
        signal: currentController.signal,
        onOpen: (id) => onOpen(id, false),
        onEvent,
        onError,
        onClose: onStreamClose,
      },
    )

    if (!currentController.signal.aborted && state.value.finishReason === null && !isTerminal(state.value.runStatus)) {
      // 流正常 resolve 但既没 done 也没走 onClose 的实现（例如自定义 mock），
      // 仍按断线处理，避免界面永久卡在 streaming。
      scheduleReconnect()
    }
  } catch (error) {
    if (isAbort(error) || currentController.signal.aborted) return
    if (error instanceof ApiRequestError && error.status >= 400 && error.status < 500) {
      // 4xx 业务错误不重连：交给现有错误/409 恢复逻辑。
      resetReconnectBudget()
      await handleApiFailure(error, attempt)
      connection.value = state.value.recovery ? 'degraded' : 'idle'
      return
    }
    if (canAutoReconnect(error)) {
      scheduleReconnect()
      return
    }
    enterDegraded('连接已断开，自动重连已停止。')
  } finally {
    reconnectInFlight = false
    if (reconnectController === currentController) reconnectController = null
    if (controller === currentController) controller = null
    flushDeltas()
    cancelRaf()
    if (!currentController.signal.aborted && connection.value !== 'reconnecting') {
      // 只有流真正结束（done/终态/降级）才收尾；重连调度中保持 streaming。
      connection.value = connection.value === 'open' ? 'idle' : connection.value
      state.value = { ...state.value, streaming: false }
      await refreshHistory().catch(() => undefined)
    }
  }
}
```

